import re, zlib, sys
sys.stdout.reconfigure(encoding='utf-8')
data = open('制造智能技术课程设计任务书.pdf','rb').read()

# 1. Extract all objects: number -> raw bytes
objs = {}
for m in re.finditer(rb'(\d+)\s+0\s+obj\b(.*?)endobj', data, re.DOTALL):
    num = int(m.group(1))
    objs[num] = m.group(2)

def get_stream(obj):
    m = re.search(rb'stream\r?\n(.*?)endstream', obj, re.DOTALL)
    if not m: return None
    raw = m.group(1).strip(b'\r\n')
    if raw.startswith(b'x\x9c') or b'FlateDecode' in obj:
        try: return zlib.decompress(raw)
        except: return raw
    return raw

# 2. Map ToUnicode: find objects containing beginbfchar/beginbfrange
cmaps = {}  # objnum -> {cid: unicode}
for num, obj in objs.items():
    s = get_stream(obj)
    if s and b'begincmap' in s:
        cmap = {}
        # beginbfchar
        for m in re.finditer(rb'beginbfchar\s*([\s\S]*?)endbfchar', s):
            block = m.group(1)
            for pair in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', block):
                cmap[int(pair.group(1),16)] = int(pair.group(2),16)
        for m in re.finditer(rb'beginbfrange\s*([\s\S]*?)endbfrange', s):
            block = m.group(1)
            for rng in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', block):
                a,b,c = int(rng.group(1),16), int(rng.group(2),16), int(rng.group(3),16)
                for i in range(b-a+1):
                    cmap[a+i] = c+i
        cmaps[num] = cmap

def decode_cid(cid, cmap):
    if cid in cmap:
        return chr(cmap[cid])
    return ''

# 3. Find font dictionaries and map font name -> cmap objnum
# Look for /Type /Font ... /ToUnicode N 0 R
font_cmap = {}
for num, obj in objs.items():
    if b'/Type /Font' in obj or b'/Type/Font' in obj:
        m = re.search(rb'/ToUnicode\s+(\d+)\s+0\s+R', obj)
        if m:
            font_cmap[num] = int(m.group(1))
        # Also find BaseFont name
        bf = re.search(rb'/BaseFont\s*/([^\s/]+)', obj)
        name = bf.group(1).decode('latin1') if bf else str(num)

# 4. Find content streams (page contents). Identify objects that are content (have BT/ET or Tf)
pages = []
for num, obj in objs.items():
    if b'/Type /Page' in obj or b'/Type/Page' in obj:
        pages.append(num)

# Get page content references
content_objs = []
for num, obj in objs.items():
    if b'/Type /Pages' in obj or b'/Type/Pages' in obj or b'/Type /Catalog' in obj:
        pass

# Simpler: find all streams with text operators
text_out = []
for num, obj in objs.items():
    s = get_stream(obj)
    if not s: continue
    if b'Tf' in s and (b'BT' in s or b'Tj' in s or b'TJ' in s):
        content_objs.append((num, s))

print("cmap fonts:", len(cmaps), "font dicts:", len(font_cmap), "content streams:", len(content_objs))
print("pages:", pages)

# Try to decode: each content stream uses a font via /Fx Tf
# Need resource mapping. Simpler heuristic: find hex strings and use ALL cmaps, try each
def try_decode(hexstr):
    bs = bytes.fromhex(hexstr.decode())
    if len(bs)==1:
        cid = bs[0]
    elif len(bs)==2:
        cid = (bs[0]<<8)|bs[1]
    else:
        return None
    for cn, cmap in cmaps.items():
        if cid in cmap:
            return chr(cmap[cid])
    return None

for num, s in content_objs:
    # collect hex strings in Tj and TJ
    for m in re.finditer(rb'<([0-9A-Fa-f]+)>', s):
        ch = try_decode(m.group(1))
        if ch:
            text_out.append(ch)
    # also add spaces/newlines on Td/TD/T*/ET
print(''.join(text_out)[:5000])
